from __future__ import annotations

import logging
from typing import Any, Dict, Optional

from fastapi import APIRouter, HTTPException
from fastapi.responses import JSONResponse

from .config import settings
from .llm_client import LLMOutputInvalid, LLMServiceError, create_llm_client
from .models import ClassifyRequest, ClassifyResponse
from .profiles.base import BaseProfile, ClassificationError
from .profiles.receipt import ReceiptProfile

logger = logging.getLogger(__name__)

router = APIRouter()

# Profile registry
_PROFILES: Dict[str, BaseProfile] = {
    "receipt": ReceiptProfile(),
}


def _error_response(
    status_code: int,
    error_code: str,
    message: str,
    attempts: Optional[int] = None,
    details: Optional[Dict[str, Any]] = None,
) -> JSONResponse:
    """Build standardized error response per error_handling.md spec."""
    payload: Dict[str, Any] = {
        "error": error_code,
        "message": message,
    }
    if attempts is not None:
        payload["attempts"] = attempts
    if details:
        payload["details"] = details
    return JSONResponse(status_code=status_code, content=payload)


def _get_profile(name: str) -> BaseProfile:
    """Get profile by name or raise 404."""
    if name not in _PROFILES:
        raise HTTPException(status_code=404, detail="profile_not_found")
    return _PROFILES[name]


@router.post("/classify", response_model=ClassifyResponse)
async def classify_artifact(request: ClassifyRequest) -> ClassifyResponse | JSONResponse:
    """Classify a document using the specified profile."""
    try:
        profile = _get_profile(request.profile)
    except HTTPException:
        return _error_response(404, "profile_not_found", f"Unknown profile: {request.profile}")

    llm = create_llm_client(settings.llm_provider)
    hints_dict = request.hints.model_dump() if request.hints else {}

    try:
        result = profile.classify(
            llm_client=llm,
            ocr_text=request.ocr_text,
            note_text=request.note_text,
            hints=hints_dict,
        )
        return ClassifyResponse(**result)

    except ClassificationError as exc:
        logger.warning("Classification failed after %d attempts: %s", exc.attempts, exc)
        return _error_response(
            422,
            "model_output_invalid",
            str(exc),
            attempts=exc.attempts,
            details={"last_error": exc.last_error} if exc.last_error else None,
        )

    except LLMOutputInvalid as exc:
        logger.warning("Classification failed due to invalid LLM output: %s", exc)
        return _error_response(422, "model_output_invalid", str(exc))

    except LLMServiceError as exc:
        logger.error("LLM service error during classification: %s", exc)
        return _error_response(503, "model_unavailable", str(exc))

    except Exception as exc:
        logger.exception("Unexpected error during classification")
        return _error_response(500, "internal_error", f"Classification failed: {exc}")

from __future__ import annotations

import logging
from abc import ABC, abstractmethod
from typing import Any, Dict, Optional

from ..llm_client import LLMClient, LLMOutputInvalid

logger = logging.getLogger(__name__)


class ClassificationError(Exception):
    """Raised when classification fails after all retries."""

    def __init__(self, message: str, attempts: int, last_error: Optional[str] = None) -> None:
        super().__init__(message)
        self.attempts = attempts
        self.last_error = last_error


class BaseProfile(ABC):
    """Abstract base class for classification profiles."""

    @property
    @abstractmethod
    def name(self) -> str:
        """Profile identifier (e.g., 'receipt')."""

    @abstractmethod
    def build_prompt(self, ocr_text: str, note_text: str, hints: Dict[str, Any]) -> str:
        """Build LLM prompt from input data."""

    @abstractmethod
    def get_schema(self) -> Dict[str, Any]:
        """Return JSON schema for LLM structured output."""

    @abstractmethod
    def normalize(self, raw_output: Dict[str, Any], hints: Dict[str, Any]) -> Dict[str, Any]:
        """Post-process LLM output into final response format."""

    def classify(
        self,
        llm_client: LLMClient,
        ocr_text: str,
        note_text: Optional[str] = None,
        hints: Optional[Dict[str, Any]] = None,
    ) -> Dict[str, Any]:
        """Run classification with retry logic."""
        hints = hints or {}
        note_text = note_text or ""
        prompt = self.build_prompt(ocr_text, note_text, hints)
        schema = self.get_schema()

        last_error: Optional[Exception] = None
        attempts = 0
        for attempt in range(3):
            attempts = attempt + 1
            try:
                raw = llm_client.classify(prompt, schema)
                return self.normalize(raw, hints)
            except LLMOutputInvalid as exc:
                logger.warning("LLM output invalid on attempt %d: %s", attempts, exc)
                last_error = exc
                if attempt < 2:
                    prompt = self._add_error_context(prompt, exc)
            except Exception as exc:
                logger.warning("LLM error on attempt %d: %s", attempts, exc)
                last_error = exc
                if attempt == 2:
                    raise

        raise ClassificationError(
            message=f"Classification failed after {attempts} attempts",
            attempts=attempts,
            last_error=str(last_error) if last_error else None,
        )

    def _add_error_context(self, prompt: str, error: Exception) -> str:
        """Enhance prompt with error feedback for retry."""
        return f"{prompt}\n\nPrevious attempt failed: {error}. Please fix the JSON output."

from __future__ import annotations

from fastapi.testclient import TestClient

from tests.conftest import MockLLMClient


class TestClassifyEndpoint:
    """Tests for POST /classify endpoint."""

    def test_success(self, client: TestClient, mock_llm_client: MockLLMClient) -> None:
        """Return 200 with valid classification for valid receipt request."""
        response = client.post(
            "/classify",
            json={
                "profile": "receipt",
                "ocr_text": "HOME DEPOT ... TOTAL 42.17 ... 12/04/25",
                "note_text": "hardware for gym project",
                "hints": {
                    "fallback_date": "2025-12-04",
                    "source_filename": "receipt_2025-12-04T15-30-12.jpg",
                    "source_channel": "email",
                    "capture_timestamp": "2025-12-04T15:30:12",
                },
            },
        )

        assert response.status_code == 200
        data = response.json()
        assert data["doc_type"] == "receipt"
        assert data["base_filename"] == "2025-12-04__HomeDepot__ShopSupplies"
        assert "base_filename" in data
        assert mock_llm_client.last_prompt is not None

    def test_invalid_profile(self, client: TestClient) -> None:
        """Return 404 for unknown profile name."""
        response = client.post(
            "/classify",
            json={
                "profile": "invalid_profile",
                "ocr_text": "some text",
            },
        )

        assert response.status_code == 404
        assert response.json()["error"] == "profile_not_found"

    def test_missing_required_field(self, client: TestClient) -> None:
        """Return 422 when required field is missing."""
        response = client.post(
            "/classify",
            json={
                "profile": "receipt",
                # Missing ocr_text
            },
        )

        assert response.status_code == 422

from __future__ import annotations

import json
import logging
from abc import ABC, abstractmethod
from typing import Any, Dict

from openai import OpenAI

from .config import settings

logger = logging.getLogger(__name__)


class LLMError(Exception):
    """Base class for LLM-related errors."""


class LLMServiceError(LLMError):
    """Raised when the LLM service is unavailable or fails."""


class LLMOutputInvalid(LLMError):
    """Raised when LLM output is malformed or does not match expected schema."""


class LLMClient(ABC):
    """Abstract base class for LLM providers."""

    @abstractmethod
    def classify(self, prompt: str, schema: Dict[str, Any]) -> Dict[str, Any]:
        """Send classification prompt and return structured output."""


class OpenAIClient(LLMClient):
    """OpenAI GPT implementation."""

    def __init__(self, api_key: str, model: str = "gpt-4o-mini") -> None:
        self.model = model
        self._client = OpenAI(api_key=api_key)

    def classify(self, prompt: str, schema: Dict[str, Any]) -> Dict[str, Any]:
        """Send classification prompt and return structured JSON output."""
        messages = [
            {"role": "system", "content": "You are a helpful assistant that outputs strict JSON."},
            {"role": "user", "content": prompt},
        ]

        try:
            response = self._client.chat.completions.create(
                model=self.model,
                messages=messages,
                response_format={"type": "json_object"},
                temperature=settings.llm_temperature,
            )
        except Exception as exc:
            logger.exception("OpenAI API request failed")
            raise LLMServiceError(f"OpenAI API error: {exc}") from exc

        content = response.choices[0].message.content
        if not content:
            raise LLMOutputInvalid("Empty response from LLM")

        try:
            return json.loads(content)
        except json.JSONDecodeError as exc:
            logger.warning("Malformed JSON from LLM: %s", content[:200])
            raise LLMOutputInvalid(f"Malformed JSON: {exc}") from exc


def create_llm_client(provider: str = "openai", **kwargs: Any) -> LLMClient:
    """Factory function to create LLM client by provider name."""
    if provider == "openai":
        return OpenAIClient(
            api_key=kwargs.get("api_key", settings.llm_api_key),
            model=kwargs.get("model", settings.llm_model),
        )
    raise ValueError(f"Unknown LLM provider: {provider}")

